<script lang="ts">
import {ui} from '../config/copy';
let {days=[]}:{days?:string[]}=$props();let now=new Date();let monday=new Date(now);monday.setDate(now.getDate()-((now.getDay()+6)%7));</script><ol class="week-dots" aria-label={ui.thisWeek}>{#each [ui.mondayInitial,ui.tuesdayInitial,ui.wednesdayInitial,ui.tuesdayInitial,ui.fridayInitial,ui.saturdayInitial,ui.saturdayInitial] as day,i}{@const date=new Date(monday.getFullYear(),monday.getMonth(),monday.getDate()+i).toLocaleDateString(ui.dateLocale)}<li class:done={days.includes(date)} class:today={i===(now.getDay()+6)%7}>{day}</li>{/each}</ol>
